import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { mkdtemp, readFile, rm, mkdir, writeFile } from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
const profile = await mkdtemp(path.join(os.tmpdir(), 'legendgirl-som-chrome-'));
const chrome = spawn('/Applications/Google Chrome.app/Contents/MacOS/Google Chrome', ['--headless=new', '--mute-audio', '--no-first-run', '--no-default-browser-check', '--autoplay-policy=no-user-gesture-required', '--remote-debugging-port=0', '--user-data-dir='+profile, 'about:blank'], {stdio:'ignore'});
let ws;
try {
 let port;
 for(let i=0;i<100;i++) { try { port=(await readFile(path.join(profile,'DevToolsActivePort'),'utf8')).split('\n')[0];break; } catch {} await new Promise(r=>setTimeout(r,100)); }
 assert.ok(port,'Chrome de QA inicializado');
 const tabs=await (await fetch('http://127.0.0.1:'+port+'/json/list')).json();
 ws=new WebSocket(tabs.find(t=>t.type==='page').webSocketDebuggerUrl);
 await new Promise(r=>ws.onopen=r);
 let id=0;const pending=new Map();ws.onmessage=e=>{const d=JSON.parse(e.data);if(d.id){pending.get(d.id)?.(d);pending.delete(d.id);}};
 const call=(method,params={})=>new Promise(resolve=>{const n=++id;pending.set(n,resolve);ws.send(JSON.stringify({id:n,method,params}));});
 const evaluate=async expression=>{const r=await call('Runtime.evaluate',{expression,awaitPromise:true,returnByValue:true});if(r.result?.exceptionDetails)throw Error(JSON.stringify(r.result.exceptionDetails));return r.result?.result?.value;};
 await call('Page.navigate',{url:'http://127.0.0.1:3000'});
 for(let i=0;i<200;i++){if(await evaluate('Boolean(window.game)'))break;await new Promise(r=>setTimeout(r,100));}
 await evaluate('game.assetsReady');
 // Valida replay mesmo quando a abertura já foi concluída e preserva o storage.
 const replay=await evaluate(`(async()=>{const {OpeningSequence,OPENING_STORAGE_KEY}=await import('/src/js/cinematics/OpeningSequence.js');const values=new Map([[OPENING_STORAGE_KEY,'1']]);const opening=new OpeningSequence({storage:{getItem:k=>values.get(k),setItem:(k,v)=>values.set(k,v)}});const normal=opening.start();const review=opening.start({replay:true});opening.update(2250);return {normal,review,active:opening.active,value:values.get(OPENING_STORAGE_KEY)};})()`);
 assert.deepEqual(replay,{normal:false,review:true,active:false,value:'1'});
 await evaluate(`game.newCampaign();game.start('NORMAL');game.saveProgress();window.reviewEvents=[];for(const name of ['PHASE1_COMPLETE','TOY_ROOM_START'])document.querySelector('#gameCanvas').addEventListener(name,()=>reviewEvents.push(name));`);
 const saved=await evaluate(`localStorage.getItem('legendGirl.campaign.v1')`);assert.ok(saved);
 const openingSaved=await evaluate(`localStorage.getItem('legendGirl.bedroom-opening.completed.v1')`);
 async function choose(phase){
  await evaluate(`(()=>{const b=document.querySelector('#btn-debug-phase-toggle');if(document.querySelector('#debug-phase-panel').hidden)b.click();const s=document.querySelector('#debug-phase-select');s.value=${JSON.stringify(phase)};s.dispatchEvent(new Event('change',{bubbles:true}));})()`);
  let selected=false;for(let i=0;i<100;i++){if(await evaluate(`document.querySelector('#debug-phase-select').value===''&&!document.querySelector('#debug-phase-select').disabled`)){selected=true;break;}await new Promise(r=>setTimeout(r,50));}assert.ok(selected,'Seletor concluiu a entrada');
  await evaluate('game.setPaused(true)');
  assert.ok(await evaluate(`document.querySelector('#debug-phase-panel').hidden&&!document.querySelector('.phase-debug-menu').contains(document.activeElement)`),'Painel recolhido e foco liberado');
 }
 for(const [width,height] of [[1280,720],[390,844]]){
  await call('Emulation.setDeviceMetricsOverride',{width,height,deviceScaleFactor:1,mobile:width<900});
  for(const phase of ['bedroom','toy-room','arena','bear-chase','toy-room','bedroom']){
   await choose(phase);
   const entry=await evaluate(`({mode:game.state.currentPhaseMode,cutscene:game.isCutsceneActive(),intro:game.toyRoomIntroduction.active,introTime:game.toyRoomIntroduction.time,arena:game.state.toyRoomInstance?.instance.arena?.state.status,elapsed:game.state.toyRoomInstance?.instance.arena?.state.elapsed,chase:game.state.toyRoomInstance?.instance.chase?.state.stage})`);
   if(phase==='bedroom'){assert.equal(entry.mode,'bedroom');assert.equal(entry.cutscene,true,'Despertar reproduzido');}
   if(phase==='toy-room'){
    assert.equal(entry.intro,true,'Chegada ilustrada reproduzida');assert.ok(entry.introTime<1);
    const ended=await evaluate(`(()=>{reviewEvents=[];game.toyRoomIntroduction.update(1500);const r=game.state.toyRoomInstance.instance;return {mode:game.state.currentPhaseMode,active:game.toyRoomIntroduction.active,events:reviewEvents,tutorial:r.tutorial.active};})()`);
    assert.equal(ended.mode,'toy-room');assert.equal(ended.active,false);assert.deepEqual(ended.events,['TOY_ROOM_START']);assert.equal(ended.tutorial,true);
   }
   if(phase==='arena'){assert.equal(entry.arena,'TRANSFORMING');assert.ok(entry.elapsed<30,'Transformação não foi pulada');}
   if(phase==='bear-chase'){assert.equal(entry.chase,'BEAR_DOWN','Revisão começa com urso caído');}
   await evaluate('game.saveProgress()');assert.equal(await evaluate(`localStorage.getItem('legendGirl.campaign.v1')`),saved,'Campanha preservada nas trocas');assert.equal(await evaluate(`localStorage.getItem('legendGirl.bedroom-opening.completed.v1')`),openingSaved,'Marca da abertura preservada');
  }
 }
 // Completar uma reprodução sem marca anterior também não cria progresso.
 const empty=await evaluate(`(async()=>{const {OpeningSequence}=await import('/src/js/cinematics/OpeningSequence.js');let writes=0;const o=new OpeningSequence({storage:{getItem:()=>null,setItem:()=>writes++}});o.start({replay:true});o.update(2250);return {writes,completed:o.hasCompleted()};})()`);
 assert.equal(empty.writes,0);assert.equal(empty.completed,false);
 console.log('APROVADO: quatro entradas narrativas, doze trocas em desktop/celular, chegada até tutorial, transformação sem salto, perseguição em BEAR_DOWN, foco e campanha preservados; replay ignora conclusão anterior sem gravar marca nova.');

} finally {ws?.close();chrome.kill();await new Promise(r=>chrome.once('exit',r));await rm(profile,{recursive:true,force:true});}
